<script setup lang="ts">
import { computed, ref } from 'vue'; import type { Message } from '../types'; import { renderMarkdown } from '../utils/markdown'
const props = defineProps<{ message: Message; canRegenerate?: boolean }>(); const emit = defineEmits<{ regenerate: [] }>(); const html = computed(() => renderMarkdown(props.message.content)); const copied = ref(false); const copy = async () => { await navigator.clipboard.writeText(props.message.content); copied.value = true; setTimeout(() => copied.value = false, 1400) }
</script>
<template><article :class="['message', message.role]"><div class="avatar">{{ message.role === 'user' ? '你' : '✦' }}</div><div class="message-body"><div class="message-name">{{ message.role === 'user' ? '你' : 'Claude' }}</div><div v-if="message.content" class="markdown" v-html="html"/><div v-else-if="message.pending" class="thinking"><i/><i/><i/> 正在思考</div><div v-if="message.sources?.length" class="sources"><a v-for="source in message.sources" :key="source.url" :href="source.url" target="_blank" rel="noreferrer">↗ {{ source.title }}</a></div><div v-if="message.role === 'assistant' && message.content" class="message-tools"><button @click="copy">{{ copied ? '已复制' : '⧉ 复制' }}</button><button v-if="canRegenerate" @click="emit('regenerate')">↻ 重新生成</button></div></div></article></template>
